using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using SplifyWin;
namespace Mcrf.Wpf {
 public sealed partial class MainWindow {
  UIElement RoutingHostsControls(){var row=new Grid{Tag="CompactStackColumns"};for(int i=0;i<5;i++)row.ColumnDefinitions.Add(new ColumnDefinition{Width=i%2==0?new GridLength(1,GridUnitType.Star):new GridLength(12)});var fields=new[]{HostSourceField("instagram","hosts · Instagram"),HostSourceField("chatgpt","hosts · ChatGPT"),Field("hosts · Дополнительные сервисы",AdditionalHostsPicker())};for(int i=0;i<fields.Length;i++){Grid.SetColumn(fields[i],i*2);row.Children.Add(fields[i]);}return row;}
  Button MultiPicker(string name,CheckBox[] checks,Func<Task> apply){
   var button=PickerButton("Не назначено");button.Name=name;button.Margin=new Thickness(0,0,0,8);var list=new StackPanel{Margin=new Thickness(12)};foreach(var c in checks){c.Style=(Style)FindResource("LabeledPacketCheck");c.Margin=new Thickness(0,4,0,8);list.Children.Add(c);}var content=new DockPanel();var footer=AsyncButton("Применить выбор",async()=>{await apply();});footer.Margin=new Thickness(12);DockPanel.SetDock(footer,Dock.Bottom);content.Children.Add(footer);content.Children.Add(new ScrollViewer{Content=list,MaxHeight=300,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});var popup=new Popup{PlacementTarget=button,Placement=PlacementMode.Bottom,StaysOpen=false,AllowsTransparency=true,Child=new Border{Background=Brush(CompactLight?"#F5F8FA":"#20262D"),BorderBrush=Brush(CompactOutline),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(10),MinWidth=240,MaxWidth=320,Child=content}};
   footer.Click+=(s,e)=>popup.IsOpen=false;button.Click+=(s,e)=>popup.IsOpen=!popup.IsOpen;button.Unloaded+=(s,e)=>popup.IsOpen=false;Action refresh=()=>{string label=String.Join(" · ",checks.Where(c=>c.IsChecked==true).Select(c=>Convert.ToString(c.Content)));SetPickerCaption(button,String.IsNullOrEmpty(label)?"Не назначено":label);button.ToolTip=label;};foreach(var c in checks){c.Checked+=(s,e)=>refresh();c.Unchecked+=(s,e)=>refresh();}refresh();return button;
  }
  static void SetPickerCaption(Button button,string caption){var panel=button.Content as DockPanel;if(panel!=null){var label=panel.Children.OfType<TextBlock>().FirstOrDefault();if(label!=null)label.Text=caption;}}
  UIElement HostSourceField(string service,string label){
   var urls=HostsCandidates.SourceUrls(service);var names=HostsCandidates.SourceNames(service);var checks=urls.Select((url,i)=>new CheckBox{Content=names[i],Tag=url}).ToArray();Button picker=null;
   Func<Task> load=async()=>{var bytes=await Task.Run(()=>File.ReadAllBytes(HostsEditor.PathName));if(picker==null||!picker.IsLoaded)return;string entries=HostsEditor.ServiceEntries(bytes,service),hash=null,legacy=null;List<string> selected=null;if(session.State.HostsAppliedHashes!=null)session.State.HostsAppliedHashes.TryGetValue(service,out hash);if(session.State.HostsSourceMultiSelections!=null)session.State.HostsSourceMultiSelections.TryGetValue(service,out selected);if(selected==null&&session.State.HostsSourceSelections!=null&&session.State.HostsSourceSelections.TryGetValue(service,out legacy))selected=new List<string>{legacy};bool known=String.IsNullOrWhiteSpace(entries)||hash==AppUpdates.TextVersion(entries);foreach(var check in checks)check.IsChecked=known&&selected!=null&&selected.Contains((string)check.Tag);if(!known&&!String.IsNullOrWhiteSpace(entries))SetPickerCaption(picker,"Назначено вручную / другой источник");};
   picker=MultiPicker("routingHosts_"+service,checks,async()=>{var selected=checks.Where(c=>c.IsChecked==true).Select(c=>(string)c.Tag).ToArray();var before=await Task.Run(()=>File.ReadAllBytes(HostsEditor.PathName));var texts=await Task.WhenAll(selected.Select(session.Core.DownloadTextAsync));string entries=String.Join("\n",selected.Select((url,i)=>HostsCandidates.Entries(HostsCandidates.ParseSource(service,url,texts[i]))).SelectMany(t=>t.Split('\n')).Where(t=>!String.IsNullOrWhiteSpace(t)).Distinct());if(!Confirm((selected.Length==0?"Удалить блок":"Применить выбранные источники")+" hosts для "+label+"? Остальные блоки сохранятся; будет резервная копия.","hosts")){await load();return;}byte[] after=HostsEditor.Compose(before,entries,service);await HostsRepair.ApplyAsync(root,HostsEditor.Managed(after),before);Exception failure=null;try{await session.ChangeConfiguration(()=>{HostsEditor.UpdateProfileEntries(session.State.ZapretProfiles,service,entries,false);RememberHostsSource(service,String.Join("\n",selected),entries);if(session.State.HostsSourceMultiSelections==null)session.State.HostsSourceMultiSelections=new Dictionary<string,List<string>>();session.State.HostsSourceMultiSelections[service]=selected.ToList();});}catch(Exception ex){failure=ex;}if(failure!=null){await HostsRepair.ApplyAsync(root,HostsEditor.Managed(before),after);throw failure;}RefreshAfterOperation(InterfaceMode==2?"WARP":"Маршрутизация");});Dispatcher.BeginInvoke(new Action(()=>LoadBasicJournal(load)));return Field(label,picker);
  }
  void RememberHostsSource(string service,string source,string entries){if(session.State.HostsSourceSelections==null)session.State.HostsSourceSelections=new Dictionary<string,string>();if(session.State.HostsAppliedHashes==null)session.State.HostsAppliedHashes=new Dictionary<string,string>();session.State.HostsSourceSelections[service]=source;session.State.HostsAppliedHashes[service]=AppUpdates.TextVersion(entries);}
 }
}

